using namespace compose;
using Clock=std::chrono::steady_clock;
struct Stats {int residuals=0,jacobians=0,products=0,model_products=0,outer=0,rejects=0,fallbacks=0;double setup_us=0;};
struct Problem {Model m;State initial;V equilibrium,mass,msqrt,misqrt;Mat modes;V frequencies;double escale;std::string regime,motion;};
Problem problem(int N,std::string regime,std::string motion){Problem p;p.regime=regime;p.motion=motion;auto&m=p.m;m.name="chain";m.count=N;m.dim=2;m.rigid=false;m.mass=V::Ones(N);m.length=V::Ones(N);m.stiffness=V::Constant(N,1000);m.gravity=V(2);m.gravity<<0,-9.81;
 double ratio=regime=="mass100"||regime=="both100"?100:1;for(int j=0;j<N;++j){m.mass[j]=2*(j%2?ratio:1)/(ratio+1);if(regime=="both100"||regime=="stiff100")m.stiffness[j]*=(j%2?1:100);}
 p.initial={V::Zero(2*N),V::Zero(2*N)};p.equilibrium=V::Zero(2*N);double downstream=m.mass.sum();V prev=V::Zero(2),eq=V::Zero(2);double large=motion=="large"?4:1;
 for(int j=0;j<N;++j){double r=1+downstream*9.81/m.stiffness[j];double angle=large*(.12*std::sin(3.141592653589793*(j+1)/(N+1))+.025*(j%2?1:-1));double stretch=large*(.025*(j%2?1:-1)+.035*std::sin(2.2*(j+1)));V e(2);e<<(r+stretch)*std::sin(angle),-(r+stretch)*std::cos(angle);prev+=e;eq[1]-=r;p.initial.x.segment<2>(2*j)=prev;p.equilibrium.segment<2>(2*j)=eq;p.initial.v[2*j]=large*(.2*std::sin(3.141592653589793*(j+1)/(N+1))+.08*(j%2?1:-1));p.initial.v[2*j+1]=large*.2*(j%2?1:-1);downstream-=m.mass[j];}
 p.mass=masses(m);p.msqrt=p.mass.cwiseSqrt();p.misqrt=p.msqrt.cwiseInverse();p.escale=std::max(1e-8,energy(m,p.initial)-minimum_energy(m));
 Mat K=Mat::Zero(2*N,2*N);for(int j=0;j<N;++j){V e=edge(m,p.equilibrium,j);double r=e.norm();V u=e/r;Mat A=m.stiffness[j]*(u*u.transpose()+(1-m.length[j]/r)*(Mat::Identity(2,2)-u*u.transpose()));K.block<2,2>(2*j,2*j)+=A;if(j){K.block<2,2>(2*j-2,2*j-2)+=A;K.block<2,2>(2*j,2*j-2)-=A;K.block<2,2>(2*j-2,2*j)-=A;}}
 Eigen::SelfAdjointEigenSolver<Mat> eig(p.misqrt.asDiagonal()*K*p.misqrt.asDiagonal());p.modes=eig.eigenvectors();p.frequencies=eig.eigenvalues().cwiseMax(0).cwiseSqrt();return p;}
struct Eval {V r;Mat J;bool valid=true;};
Eval evaluate(const Problem&p,const State&old,const V&x,double h,bool jac,Stats&stats){++stats.residuals;if(jac)++stats.jacobians;int n=x.size();V F=V::Zero(n);Mat dF;if(jac)dF=Mat::Zero(n,n);for(int j=0;j<p.m.count;++j)F.segment<2>(2*j)=p.m.mass[j]*p.m.gravity;
 for(int j=0;j<p.m.count;++j){V a=edge(p.m,old.x,j),b=edge(p.m,x,j);double ra=a.norm(),rb=b.norm(),den=ra+rb;if(ra<1e-12||rb<1e-12)return {V::Constant(n,NAN),Mat(),false};double t=1-2*p.m.length[j]/den;V fj=-.5*p.m.stiffness[j]*t*(a+b);F.segment<2>(2*j)+=fj;if(j)F.segment<2>(2*j-2)-=fj;
 if(jac){Mat A=-.5*p.m.stiffness[j]*(t*Mat::Identity(2,2)+(2*p.m.length[j]/(den*den))*(a+b)*(b/rb).transpose());dF.block<2,2>(2*j,2*j)+=A;if(j){dF.block<2,2>(2*j-2,2*j-2)+=A;dF.block<2,2>(2*j,2*j-2)-=A;dF.block<2,2>(2*j-2,2*j)-=A;}}}
 Eval e;e.r=p.mass.cwiseProduct(x-old.x-h*old.v)-.5*h*h*F;if(jac)e.J=p.mass.asDiagonal().toDenseMatrix()-.5*h*h*dF;e.valid=e.r.allFinite()&&(!jac||e.J.allFinite());return e;}
struct Metric {std::string name;V diagonal;Mat L,T;const Problem*p;double h;double initial_setup_us=0;
 Metric(const Problem&pr,double step,std::string id):name(id),p(&pr),h(step){auto start=Clock::now();int n=pr.mass.size();V d=pr.mass;Mat H=pr.mass.asDiagonal().toDenseMatrix();for(int j=0;j<pr.m.count;++j){double k=.25*h*h*pr.m.stiffness[j];d.segment<2>(2*j).array()+=k;H.block<2,2>(2*j,2*j)+=k*Mat::Identity(2,2);if(j){d.segment<2>(2*j-2).array()+=k;H.block<2,2>(2*j-2,2*j-2)+=k*Mat::Identity(2,2);H.block<2,2>(2*j,2*j-2)-=k*Mat::Identity(2,2);H.block<2,2>(2*j-2,2*j)-=k*Mat::Identity(2,2);}}if(name=="diagonal")diagonal=d.cwiseSqrt().cwiseInverse();else if(name=="mass"||name=="svd_rows")diagonal=pr.misqrt;else diagonal=V::Ones(n);if(name=="graph")L=H.llt().matrixL();initial_setup_us=std::chrono::duration<double,std::micro>(Clock::now()-start).count();}
 void update(const Mat&J,Stats&s){if(name!="svd_rows")return;auto start=Clock::now();Mat A=p->misqrt.asDiagonal()*J*p->misqrt.asDiagonal();Eigen::JacobiSVD<Mat> svd(A,Eigen::ComputeThinU|Eigen::ComputeThinV);V sig=svd.singularValues();double floor=.05*std::max(1e-10,sig[sig.size()/2]);V w=(sig.array().square()+floor*floor).sqrt().inverse();T=svd.matrixU()*w.asDiagonal()*svd.matrixU().transpose();s.setup_us+=std::chrono::duration<double,std::micro>(Clock::now()-start).count();}
 V right(const V&y)const{if(name=="graph")return L.transpose().triangularView<Eigen::Upper>().solve(y);return diagonal.cwiseProduct(y);}
 V left(const V&r)const{if(name=="graph")return L.triangularView<Eigen::Lower>().solve(r);V q=diagonal.cwiseProduct(r);if(name=="svd_rows")q=T*q;return q;}
};
struct Linear {V y;int used;double residual;};
Linear gmres(const Mat&J,const V&r,Metric&metric,int budget,double relative,Stats&s){V b=-metric.left(r);int n=b.size(),kmax=std::min(n,budget);double beta=b.norm();Linear out{V::Zero(n),0,beta};if(beta<1e-30||kmax==0)return out;Mat Q=Mat::Zero(n,kmax+1),H=Mat::Zero(kmax+1,kmax);V cs=V::Zero(kmax),sn=V::Zero(kmax),g=V::Zero(kmax+1);Q.col(0)=b/beta;g[0]=beta;int used=0;
 for(int k=0;k<kmax;++k){V w=metric.left(J*metric.right(Q.col(k)));++s.products;for(int j=0;j<=k;++j){H(j,k)=Q.col(j).dot(w);w-=H(j,k)*Q.col(j);}for(int j=0;j<=k;++j){double t=Q.col(j).dot(w);H(j,k)+=t;w-=t*Q.col(j);}H(k+1,k)=w.norm();bool breakdown=H(k+1,k)<1e-14;if(!breakdown)Q.col(k+1)=w/H(k+1,k);for(int j=0;j<k;++j){double a=cs[j]*H(j,k)+sn[j]*H(j+1,k);H(j+1,k)=-sn[j]*H(j,k)+cs[j]*H(j+1,k);H(j,k)=a;}double den=std::hypot(H(k,k),H(k+1,k));cs[k]=den>0?H(k,k)/den:1;sn[k]=den>0?H(k+1,k)/den:0;H(k,k)=cs[k]*H(k,k)+sn[k]*H(k+1,k);H(k+1,k)=0;g[k+1]=-sn[k]*g[k];g[k]=cs[k]*g[k];used=k+1;if(std::abs(g[k+1])<=relative*beta||breakdown)break;}
 if(used){V y=H.topLeftCorner(used,used).triangularView<Eigen::Upper>().solve(g.head(used));out.y=Q.leftCols(used)*y;}out.used=used;out.residual=std::abs(g[used]);return out;}
struct Step {State state;Stats stats;bool finite=true,converged=false;std::string failure;double residual=0;};
Step step(const Problem&p,const State&old,double h,Metric&metric,int budget,std::string globalizer,bool direct=false){Step out;V x=old.x+h*old.v;const double scale=std::max(1e-12,h*std::sqrt(2*p.escale));double radius=2;int limit=budget==0?60:12,maxproducts=budget==0?20000:budget;double tol=budget==0?1e-10:1e-8;int maxeval=budget==0?500:80;auto norm=[&](const V&r){return p.misqrt.cwiseProduct(r).norm()/scale;};
 for(int k=0;k<limit&&out.stats.residuals<maxeval;++k){Eval e=evaluate(p,old,x,h,true,out.stats);if(!e.valid){out.finite=false;out.failure="invalid_edge";break;}out.residual=norm(e.r);if(out.residual<tol){out.converged=true;break;}if(!direct&&out.stats.products>=maxproducts)break;++out.stats.outer;V dx;
 if(direct)dx=e.J.fullPivLu().solve(-e.r);else{metric.update(e.J,out.stats);int chunk=budget==0?int(x.size()):std::max(4,budget/4);Linear lin=gmres(e.J,e.r,metric,std::min(chunk,maxproducts-out.stats.products),budget==0?1e-12:1e-3,out.stats);dx=metric.right(lin.y);}
 if(!dx.allFinite()){out.finite=false;out.failure="nonfinite_linear_update";break;}V weighted=p.misqrt.cwiseProduct(e.r),Jdx=e.J*dx;++out.stats.model_products;double phi=.5*weighted.squaredNorm(),slope=weighted.dot(p.misqrt.cwiseProduct(Jdx));
 if(slope>=0||dx.norm()<1e-18){V g=e.J.transpose()*p.misqrt.cwiseProduct(weighted);V Jg=e.J*g;++out.stats.model_products;double den=p.misqrt.cwiseProduct(Jg).squaredNorm();if(den<1e-40){out.failure="stationary_residual_nonroot";break;}dx=-g*(g.squaredNorm()/den);Jdx=e.J*dx;++out.stats.model_products;slope=weighted.dot(p.misqrt.cwiseProduct(Jdx));++out.stats.fallbacks;}
 bool accepted=false;V candidate=x;int trials=globalizer=="trust"?10:14;double alpha=1;
 for(int ls=0;ls<trials&&out.stats.residuals<maxeval;++ls){double cap=1;if(globalizer=="trust"){double dn=p.msqrt.cwiseProduct(dx).norm()/scale;cap=std::min(1.,radius/std::max(1e-30,dn));}else cap=alpha;V d=cap*dx;candidate=x+d;Eval next=evaluate(p,old,candidate,h,false,out.stats);double actual=next.valid?phi-.5*p.misqrt.cwiseProduct(next.r).squaredNorm():-INFINITY;
 if(globalizer=="trust"){double predicted=phi-.5*p.misqrt.cwiseProduct(e.r+cap*Jdx).squaredNorm();double rho=predicted>0?actual/predicted:-INFINITY;if(rho<.25)radius*=.25;else if(rho>.75&&cap<1)radius=std::min(100.,2*radius);if(next.valid&&rho>1e-4&&actual>0){accepted=true;break;}}
 else if(next.valid&&actual>=-1e-4*alpha*slope){accepted=true;break;}else alpha*=.5;++out.stats.rejects;}
 if(!accepted){out.failure=globalizer=="trust"?"trust_stall":"line_search_stall";break;}x=candidate;
 }
 Eval final=evaluate(p,old,x,h,false,out.stats);out.residual=final.valid?norm(final.r):INFINITY;out.converged=out.residual<tol;out.state={x,2*(x-old.x)/h-old.v};out.finite=out.finite&&compose::finite(out.state)&&final.valid;if(!out.converged&&out.failure.empty())out.failure="budget_or_iteration_limit";return out;}
struct ModeError {double relative=0,phase=0,high=0;};
ModeError mode_error(const Problem&p,const State&s,const State&reference){V a=p.modes.transpose()*p.msqrt.cwiseProduct(s.x-p.equilibrium),b=p.modes.transpose()*p.msqrt.cwiseProduct(s.v),ar=p.modes.transpose()*p.msqrt.cwiseProduct(reference.x-p.equilibrium),br=p.modes.transpose()*p.msqrt.cwiseProduct(reference.v);V A=p.frequencies.cwiseProduct(a),Ar=p.frequencies.cwiseProduct(ar);V er=.5*(Ar.array().square()+br.array().square()).matrix(),es=.5*(A.array().square()+b.array().square()).matrix();ModeError out;double total=std::max(1e-20,er.sum());out.relative=std::sqrt(((A-Ar).squaredNorm()+(b-br).squaredNorm())/(2*total));double weighted=0,weights=0;for(int k=0;k<a.size();++k)if(er[k]>1e-6*total){double phase=std::remainder(std::atan2(A[k],b[k])-std::atan2(Ar[k],br[k]),2*3.141592653589793);weighted+=er[k]*phase*phase;weights+=er[k];}out.phase=std::sqrt(weighted/std::max(1e-20,weights));int high=std::max(1,int(a.size()/4));out.high=std::abs(es.tail(high).sum()-er.tail(high).sum())/total;return out;}
void require(bool test,const std::string&s){if(!test)throw std::runtime_error(s);}
void audits(){std::ofstream f("identity_tests.txt");f<<std::setprecision(14);for(int N:{2,8,32})for(std::string regime:{"uniform","mass100","stiff100","both100"}){Problem p=problem(N,regime,"mixed");double h=.04;Stats stats;V x=p.initial.x+h*p.initial.v;Eval e=evaluate(p,p.initial,x,h,true,stats);V d=V::LinSpaced(x.size(),-.7,.9);double eps=1e-6;V fd=(evaluate(p,p.initial,x+eps*d,h,false,stats).r-evaluate(p,p.initial,x-eps*d,h,false,stats).r)/(2*eps);double error=(fd-e.J*d).norm()/std::max(1.,fd.norm());f<<"jacobian N="<<N<<" regime="<<regime<<" relative="<<error<<"\n";require(error<3e-7,"analytic Jacobian");State trial{x,2*(x-p.initial.x)/h-p.initial.v};double identity=std::abs(energy(p.m,trial)-energy(p.m,p.initial)-2*e.r.dot(x-p.initial.x)/(h*h))/p.escale;f<<"energy_residual_identity N="<<N<<" regime="<<regime<<" error="<<identity<<"\n";require(identity<1e-9,"energy residual identity");Metric raw(p,h,"none");Step reference=step(p,p.initial,h,raw,0,"line",true);require(reference.converged,"direct reference convergence");for(std::string id:{"none","mass","diagonal","graph","svd_rows"}){Metric metric(p,h,id);metric.update(e.J,stats);Mat transformed=Mat::Zero(x.size(),x.size());for(int col=0;col<x.size();++col){V unit=V::Zero(x.size());unit[col]=1;transformed.col(col)=metric.left(e.J*metric.right(unit));}Eigen::JacobiSVD<Mat> spectrum(transformed);V sig=spectrum.singularValues();f<<"conditioning N="<<N<<" regime="<<regime<<" metric="<<id<<" condition="<<sig[0]/sig[sig.size()-1]<<"\n";Step r=step(p,p.initial,h,metric,0,"line");double delta=(r.state.x-reference.state.x).norm()+(r.state.v-reference.state.v).norm();double de=std::abs(energy(p.m,r.state)-energy(p.m,p.initial))/p.escale;f<<"root N="<<N<<" regime="<<regime<<" metric="<<id<<" converged="<<r.converged<<" difference="<<delta<<" energy="<<de<<" products="<<r.stats.products<<"\n";require(r.converged&&delta<2e-6&&de<1e-8,"transformed converged root agreement");}}
 f<<"PASS derivative and converged-root identity checks\n";}
void timing(){std::ofstream f("timing.csv");f<<std::setprecision(12)<<"N,regime,metric,budget,repeat,steps,converged_steps,products,residuals,setup_us,cpu_ms,wall_ms\n";std::vector<std::string> ids={"none","mass","diagonal","graph","svd_rows"};for(int rep=0;rep<7;++rep){std::rotate(ids.begin(),ids.begin()+1,ids.end());for(int N:{2,8,32})for(std::string regime:{"mass100","both100"})for(std::string id:ids)for(int budget:{12,48}){Problem p=problem(N,regime,"mixed");double h=.04;auto wall=Clock::now();auto cpu=std::clock();Metric metric(p,h,id);State s=p.initial;int products=0,residuals=0,converged=0,steps=0;double setup=metric.initial_setup_us;for(int k=0;k<10;++k){Step r=step(p,s,h,metric,budget,"line");products+=r.stats.products;residuals+=r.stats.residuals;setup+=r.stats.setup_us;if(!r.finite)break;s=r.state;++steps;if(r.converged)++converged;}double cpums=1000.*(std::clock()-cpu)/CLOCKS_PER_SEC,wallms=std::chrono::duration<double,std::milli>(Clock::now()-wall).count();f<<N<<","<<regime<<","<<id<<","<<budget<<","<<rep<<","<<steps<<","<<converged<<","<<products<<","<<residuals<<","<<setup<<","<<cpums<<","<<wallms<<"\n";}}}
int main(int argc,char**argv){try{Eigen::setNbThreads(1);audits();if(argc>1&&std::string(argv[1])=="--tests")return 0;if(argc>1&&std::string(argv[1])=="--timing"){timing();return 0;}std::ofstream out("runs.csv"),trace("selected_traces.csv"),refs("references.csv");out<<std::setprecision(12);trace<<std::setprecision(12);refs<<std::setprecision(12);
 out<<"N,regime,motion,h,metric,globalizer,budget,requested_steps,completed_steps,converged_steps,reference_steps,matched_steps,max_residual,max_energy_drift,rms_position_error,rms_velocity_error,max_mode_error,max_phase_error,max_highmode_error,products,model_products,residual_evaluations,jacobians,outer,rejections,fallbacks,stalled_steps,budget_limited_steps,setup_us,cpu_ms,wall_ms,failure,last_step_failure\n";
 trace<<"N,regime,motion,h,metric,globalizer,budget,step,residual,energy_drift,position_error,velocity_error,mode_error,phase_error,highmode_error,converged,step_failure\n";refs<<"N,regime,motion,h,requested_steps,completed_steps,max_energy_drift,failure\n";
 int runs=0;for(int N:{2,8,32})for(std::string regime:{"uniform","mass100","stiff100","both100"})for(std::string motion:{"mixed","large"})for(double h:(motion=="mixed"?std::vector<double>{.01,.04}:std::vector<double>{.1})){Problem p=problem(N,regime,motion);int steps=int(std::round(.4/h));std::vector<State> reference{p.initial};Metric reference_metric(p,h,"none");State sr=p.initial;double refde=0;std::string reffail;for(int k=0;k<steps;++k){Step r=step(p,sr,h,reference_metric,0,"line",true);if(!r.finite||!r.converged){reffail=r.failure;break;}sr=r.state;reference.push_back(sr);refde=std::max(refde,std::abs(energy(p.m,sr)-energy(p.m,p.initial))/p.escale);}refs<<N<<","<<regime<<","<<motion<<","<<h<<","<<steps<<","<<reference.size()-1<<","<<refde<<","<<reffail<<"\n";
 for(std::string metricid:{"none","mass","diagonal","graph","svd_rows"})for(std::string globalizer:{"line","trust"})for(int budget:{12,48}){auto start=Clock::now();std::clock_t cpu=std::clock();Metric metric(p,h,metricid);Stats total;total.setup_us=metric.initial_setup_us;State s=p.initial;double maxr=0,maxde=0,sumx=0,sumv=0,maxmode=0,maxphase=0,maxhigh=0;int completed=0,converged=0,matched=0,stalled=0,budgetlimited=0;std::string failure,lastfailure;for(int k=0;k<steps;++k){Step r=step(p,s,h,metric,budget,globalizer);total.products+=r.stats.products;total.model_products+=r.stats.model_products;total.residuals+=r.stats.residuals;total.jacobians+=r.stats.jacobians;total.outer+=r.stats.outer;total.rejects+=r.stats.rejects;total.fallbacks+=r.stats.fallbacks;total.setup_us+=r.stats.setup_us;if(!r.converged){lastfailure=r.failure;if(r.failure=="budget_or_iteration_limit")++budgetlimited;else ++stalled;}if(!r.finite){failure=r.failure;break;}s=r.state;++completed;if(r.converged)++converged;maxr=std::max(maxr,r.residual);double de=std::abs(energy(p.m,s)-energy(p.m,p.initial))/p.escale;maxde=std::max(maxde,de);double xe=NAN,ve=NAN;ModeError me;if(k+1<int(reference.size())){++matched;xe=p.msqrt.cwiseProduct(s.x-reference[k+1].x).norm()/std::sqrt(p.mass.sum());ve=p.msqrt.cwiseProduct(s.v-reference[k+1].v).norm()/std::sqrt(p.mass.sum());sumx+=xe*xe;sumv+=ve*ve;me=mode_error(p,s,reference[k+1]);maxmode=std::max(maxmode,me.relative);maxphase=std::max(maxphase,me.phase);maxhigh=std::max(maxhigh,me.high);}if(N==32&&(regime=="both100"||regime=="mass100"))trace<<N<<","<<regime<<","<<motion<<","<<h<<","<<metricid<<","<<globalizer<<","<<budget<<","<<k+1<<","<<r.residual<<","<<de<<","<<xe<<","<<ve<<","<<(k+1<int(reference.size())?me.relative:NAN)<<","<<(k+1<int(reference.size())?me.phase:NAN)<<","<<(k+1<int(reference.size())?me.high:NAN)<<","<<r.converged<<","<<r.failure<<"\n";if(de>1e6||s.x.norm()>1e7){failure="runaway_energy_or_position";break;}}
 double cpums=1000.*(std::clock()-cpu)/CLOCKS_PER_SEC,wall=std::chrono::duration<double,std::milli>(Clock::now()-start).count();if(completed==steps&&converged<steps)failure="completed_with_unconverged_steps";out<<N<<","<<regime<<","<<motion<<","<<h<<","<<metricid<<","<<globalizer<<","<<budget<<","<<steps<<","<<completed<<","<<converged<<","<<reference.size()-1<<","<<matched<<","<<maxr<<","<<maxde<<","<<(matched?std::sqrt(sumx/matched):NAN)<<","<<(matched?std::sqrt(sumv/matched):NAN)<<","<<(matched?maxmode:NAN)<<","<<(matched?maxphase:NAN)<<","<<(matched?maxhigh:NAN)<<","<<total.products<<","<<total.model_products<<","<<total.residuals<<","<<total.jacobians<<","<<total.outer<<","<<total.rejects<<","<<total.fallbacks<<","<<stalled<<","<<budgetlimited<<","<<total.setup_us<<","<<cpums<<","<<wall<<","<<failure<<","<<lastfailure<<"\n";++runs;}std::cout<<"completed N="<<N<<" "<<regime<<" "<<motion<<" h="<<h<<" runs="<<runs<<"\n";out.flush();trace.flush();refs.flush();}
 std::cout<<"DONE "<<runs<<" runs\n";return 0;}catch(const std::exception&e){std::cerr<<"ERROR "<<e.what()<<"\n";return 1;}}
